def load_config(defaults: dict, env: dict) -> dict:
    """Return a copy of `defaults` where any env var APP_<KEY> overrides the
    value for key <key> (lowercased), coerced to the type of the default."""
    cfg = dict(defaults)
    for key, value in env.items():
        if not key.startswith("APP_"):
            continue
        target = key[len("APP_"):].lower()
        if target not in cfg:
            continue
        cfg[target] = _coerce(cfg[target], value)
    return cfg


def _coerce(default, value):
    """Coerce `value` (typically a string from the environment) to the type of
    `default` (bool, int, float, or str)."""
    # bool must be checked before int, since bool is a subclass of int.
    if isinstance(default, bool):
        return _coerce_bool(value)
    if isinstance(default, int):
        return int(value)
    if isinstance(default, float):
        return float(value)
    if isinstance(default, str):
        return str(value)
    return value


def _coerce_bool(value):
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in ("true", "1", "yes", "y", "on"):
        return True
    if text in ("false", "0", "no", "n", "off", ""):
        return False
    raise ValueError(f"cannot coerce {value!r} to bool")

import unittest
from cfg import load_config

class TestLoader(unittest.TestCase):
    def test_override_int(self):
        cfg = load_config({"port": 80, "host": "x"}, {"APP_PORT": "8080"})
        self.assertEqual(cfg["port"], 8080)
        self.assertEqual(cfg["host"], "x")

    def test_override_float(self):
        cfg = load_config({"ratio": 0.5}, {"APP_RATIO": "1.25"})
        self.assertEqual(cfg["ratio"], 1.25)
        self.assertIsInstance(cfg["ratio"], float)

    def test_override_bool(self):
        cfg = load_config({"debug": False}, {"APP_DEBUG": "true"})
        self.assertIs(cfg["debug"], True)
        cfg = load_config({"debug": True}, {"APP_DEBUG": "0"})
        self.assertIs(cfg["debug"], False)

    def test_override_str(self):
        cfg = load_config({"host": "x"}, {"APP_HOST": "example.com"})
        self.assertEqual(cfg["host"], "example.com")

    def test_non_app_env_ignored(self):
        cfg = load_config({"port": 80}, {"PORT": "8080", "PATH": "/bin"})
        self.assertEqual(cfg["port"], 80)

    def test_unknown_key_ignored(self):
        cfg = load_config({"port": 80}, {"APP_TIMEOUT": "30"})
        self.assertEqual(cfg, {"port": 80})

    def test_defaults_not_mutated(self):
        defaults = {"port": 80}
        load_config(defaults, {"APP_PORT": "8080"})
        self.assertEqual(defaults, {"port": 80})

    def test_no_env(self):
        cfg = load_config({"port": 80, "host": "x"}, {})
        self.assertEqual(cfg, {"port": 80, "host": "x"})

if __name__ == "__main__":
    unittest.main()
